package com.nexora.reports.translation2.domain;

import com.nexora.reports.translation.domain.SqlParameter;

import java.util.List;
import java.util.Objects;

/**
 * The parameterized SELECT of one dataset of a report plan ({@code nexora-logical-plan/2}). The text contains only
 * quoted identifiers taken from the plan's natural keys, aliases generated by position ({@code "t0"}, {@code "c1"}),
 * fixed keywords and {@code CAST(? AS type)} placeholders; every value is in {@link #parameters()}. The last
 * parameter is the row limit, {@code maxRows + 1}, to detect truncation.
 *
 * @param outputs result columns in SELECT order (the order of the plan's {@code output.columns})
 * @param schema  what the executor must verify in the live database, in the same transaction, before reading
 */
public record SqlQueryV2(String datasetId, String sql, List<SqlParameter> parameters, List<Output> outputs,
                         int maxRows, SchemaRequirementsV2 schema) {

    public SqlQueryV2 {
        Objects.requireNonNull(datasetId, "datasetId");
        Objects.requireNonNull(sql, "sql");
        parameters = List.copyOf(parameters);
        outputs = List.copyOf(outputs);
        Objects.requireNonNull(schema, "schema");
        if (maxRows < 1) {
            throw new IllegalArgumentException("maxRows must be positive");
        }
    }

    /** One result column: its position (1-based, SQL alias {@code "c<position>"}) and how to read it. */
    public record Output(int position, String output, String valueType, String role, boolean hidden) {
    }

    /** Never prints the SQL parameters: they may contain business data. */
    @Override
    public String toString() {
        return "SqlQueryV2[" + datasetId + ", " + outputs.size() + " columns, " + parameters.size() + " parameters]";
    }
}
